@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {}

class Subdivision {}

class Employee {}

class Customer {}

class Account {
  + accountNumber : int
  + balance : double
  + interestRate : float
  + monthlyFee : float
}

class MortgageAccount extends Account {
  + property : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class Privilege {}

class Manager {}

Employee extends Manager

Manager "1" -- "*" Division : manages
Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
OOBank "1" -- "*" Division
OOBank "1" -- "*" Branch
Branch "1" -- "*" Account : opens
Customer "1" -- "*" Account : owns
Account "1" -- "*" Privilege : has
Account "0..1" -- "*" SecondaryCard : has
Customer "*" -- "0..1" Employee : personal banker

@enduml

